'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var zeros = require( '@stdlib/array/base/zeros' );
var incrnanvmr = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanvmr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanvmr(), 'function', 'returns expected value' );
	t.end();
});

tape( 'the function returns an accumulator function (known mean)', function test( t ) {
	t.strictEqual( typeof incrnanvmr( 3.0 ), 'function', 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a non-numeric value', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanvmr( value );
		};
	}
});

tape( 'the accumulator function incrementally computes a variance-to-mean ratio', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var i;

	data = [ 2.0, 3.0, NaN, 2.0, 4.0, NaN, 3.0, 4.0 ];

	acc = incrnanvmr();
	expected = [];
	actual = zeros( data.length );

	for ( i = 0; i < data.length; i++ ) {
		actual[i] = acc( data[i] );

		// compute expected ignoring NaNs:
		var valid = data.slice(0, i+1).filter( function(d){ return !isnan(d); });
		if ( valid.length === 0 ) {
			expected[i] = null;
		} else if ( valid.length === 1 ) {
			expected[i] = 0.0 / ( valid[0] ); // single datum: VMR=0
		} else {
			var mean = valid.reduce((a,b)=>a+b,0)/valid.length;
			var M2 = valid.reduce( (s,x) => s + (x-mean)*(x-mean), 0);
			expected[i] = ( M2 / (valid.length-1) ) / mean;
			}
	}
	t.deepEqual( actual, expected, 'returns expected results' );
	t.end();
});

tape( 'the accumulator function incrementally computes a variance-to-mean ratio (known mean)', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var i;

	data = [ 2.0, NaN, 3.0, 2.0, NaN, 4.0, 3.0 ];

	acc = incrnanvmr( 3.0 );
	expected = [];
	actual = zeros( data.length );

	for ( i = 0; i < data.length; i++ ) {
		actual[i] = acc( data[i] );

		// compute expected ignoring NaNs:
		var valid = data.slice(0,i+1).filter( function(d){ return !isnan(d); });
		if ( valid.length === 0 ) {
			expected[i] = null;
		} else {
			var M2 = valid.reduce( (s,x) => s + (x-3.0)*(x-3.0), 0 );
			expected[i] = ( M2 / valid.length ) / 3.0;
		}
	}
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current variance-to-mean ratio', function test( t ) {
	var data;
	var acc;
	var i;

	data = [ 2.0, NaN, 3.0, 1.0 ];
	acc = incrnanvmr();
	for ( i = 0; i < data.length; i++ ) {
		acc( data[i] );
	}

	var expectedValid = data.filter(d => !isnan(d));
	var mean = expectedValid.reduce((a,b)=>a+b,0)/expectedValid.length;
	var M2 = expectedValid.reduce((s,x)=>s+(x-mean)*(x-mean),0);
	var expected = ( M2/(expectedValid.length-1) ) / mean;

	t.strictEqual( acc(), expected, 'returns expected value' );
	t.end();
});

tape( 'the accumulated value is `null` until at least 1 datum has been provided (unknown mean)', function test( t ) {
	var acc;
	var D;

	acc = incrnanvmr();

	D = acc();
	t.strictEqual( D, null, 'returns expected value' );

	D = acc( 3.0 );
	t.notEqual( D, null, 'does not return null' );

	D = acc();
	t.notEqual( D, null, 'does not return null' );

	t.end();
});

tape( 'the accumulated value is `null` until at least 1 datum has been provided (known mean)', function test( t ) {
	var acc;
	var D;

	acc = incrnanvmr( 3.0 );

	D = acc();
	t.strictEqual( D, null, 'returns expected value' );

	D = acc( 3.0 );
	t.notEqual( D, null, 'does not return null' );

	D = acc();
	t.notEqual( D, null, 'does not return null' );

	t.end();
});

tape( 'the accumulated value is `0` until at least 2 datums have been provided (unknown mean)', function test( t ) {
	var acc;
	var D;

	acc = incrnanvmr();

	D = acc( 2.0 );
	t.strictEqual( D, 0.0, 'returns expected value' );

	D = acc();
	t.strictEqual( D, 0.0, 'returns expected value' );

	D = acc( 3.0 );
	t.notEqual( D, 0.0, 'does not return 0' );

	D = acc();
	t.notEqual( D, 0.0, 'does not return 0' );

	t.end();
});

tape( 'the accumulator function ignores NaNs for all future invocations', function test( t ) {
	var data = [ 2.0, NaN, 1.0, 3.0 ];
	var acc = incrnanvmr();
	var results = [];
	var i;

	for ( i = 0; i < data.length; i++ ) {
		results.push( acc( data[ i ] ) );
	}

	t.deepEqual(
	results,
	[ 0.0, 0.0, 0.3333333333333333, 0.5 ],
	'NaNs are ignored and do not break accumulator'
);
	t.end();
});
